Lemma total_arg_bytes_firstn_S : forall (l : list (list byte)) k,
  (k < length l)%nat ->
  total_arg_bytes_nat (firstn (S k) l)
  = (total_arg_bytes_nat (firstn k l) + length (nth k l []) + 1)%nat.
